1	package tariff
2	
3	import (
4		"fmt"
5		"testing"
6		"time"
7	)
8	
9	// “版本尚未生效”的首次拒绝也会被保存的回归测试。
10	//
11	// 时间线（注入时钟，不依赖真实时间跨过生效边界）：
12	//
13	//	版本 seat/v-next：单价 250 分，at(100) 起生效（含），at(200) 结束（不含）
14	//	首次报价：at(50)，生效前 → 受理但拒绝，原因 version_not_yet_effective
15	//	重试点：at(100) 生效时刻本身、at(150) 生效后仍在结束时间之前
16	//
17	// 约定：非空请求标识的首次结果（无论确认还是拒绝）都会被保存；
18	// 版本生效后用原标识原样重试仍返回那次首次拒绝，只有换用从未使用过的
19	// 新标识才能按已生效的版本确认报价。
20	func TestNotYetEffectiveRejectionSurvivesEffectiveInstant(t *testing.T) {
21		now, setNow := fixedClock(at(50))
22		b := NewBook(WithClock(now))
23	
24		// 单价为整数分、数量为合法正整数、结束时间晚于开始时间：
25		// 场景中不混入数量错误或金额溢出。
26		if err := b.RegisterVersion(RegisterRequest{
27			ItemID: "seat", VersionID: "v-next", UnitPrice: 250,
28			Start: at(100), End: atPtr(200),
29		}); err != nil {
30			t.Fatalf("register v-next: %v", err)
31		}
32	
33		req := QuoteRequest{RequestID: "early", ItemID: "seat", VersionID: "v-next", Quantity: 3}
34	
35		// 生效前首次提交：调用本身不返回错误，结果是未确认的拒绝。
36		first, err := b.Quote(req)
37		if err != nil {
38			t.Fatalf("拒绝是正常受理，err 应为空: %v", err)
39		}
40		if first.Confirmed {
41			t.Fatalf("生效前报价不能确认: %+v", first)
42		}
43		if first.Reason != ReasonVersionNotYetEffective {
44			t.Fatalf("拒绝原因=%q, want %q", first.Reason, ReasonVersionNotYetEffective)
45		}
46		if first.UnitPrice != 0 || first.Total != 0 {
47			t.Fatalf("拒绝结果单价和总价都应为零: 单价=%d 总价=%d", first.UnitPrice, first.Total)
48		}
49		// 完整保留请求标识、费率项、版本、数量和首次受理时刻。
50		if first.Request != req {
51			t.Fatalf("首次结果未保留原请求内容: %+v vs %+v", first.Request, req)
52		}
53		if !first.AcceptedAt.Equal(at(50)) {
54			t.Fatalf("首次受理时刻=%v, want %v", first.AcceptedAt, at(50))
55		}
56	
57		// 首次拒绝也会保存：按标识查询能找到这份拒绝，而不是当作未受理过。
58		got, err := b.Lookup("early")
59		if err != nil {
60			t.Fatalf("首次拒绝应可按标识查询: %v", err)
61		}
62		if got != first {
63			t.Fatalf("查询结果与首次拒绝不一致: %+v vs %+v", got, first)
64		}
65	
66		// 进入有效期的两个代表时刻：生效起点本身（含在有效区间内）、
67		// 以及生效后仍在结束时间之前。
68		for _, instant := range []time.Time{at(100), at(150)} {
69			setNow(instant)
70	
71			// 原标识原内容重试：仍是先前的拒绝，不按当前费率重新计算，
72			// 受理时刻仍是首次受理的 at(50)。生效起点上的拒绝来自幂等保留，
73			// 不能误当作版本依旧不可用——下面用新标识确认这一点。
74			replay, err := b.Quote(req)
75			if err != nil {
76				t.Fatalf("%v 重试: %v", instant, err)
77			}
78			if replay != first {
79				t.Fatalf("%v 重试被重算: %+v -> %+v", instant, first, replay)
80			}
81			if replay.Confirmed || replay.Reason != ReasonVersionNotYetEffective ||
82				replay.UnitPrice != 0 || replay.Total != 0 {
83				t.Fatalf("%v 重试必须仍是首次拒绝: %+v", instant, replay)
84			}
85			if !replay.AcceptedAt.Equal(at(50)) {
86				t.Fatalf("%v 重试的受理时刻被改写: %v", instant, replay.AcceptedAt)
87			}
88	
89			// 查询也继续指向第一次受理的请求与时间。
90			got, err := b.Lookup("early")
91			if err != nil {
92				t.Fatalf("%v 查询原标识: %v", instant, err)
93			}
94			if got != first {
95				t.Fatalf("%v 查询结果被改写: %+v -> %+v", instant, first, got)
96			}
97	
98			// 换用从未使用过的标识，费率项、版本、数量一致：
99			// 版本已生效，新报价正常确认，单价来自所引用版本，总价为单价乘数量。
100			freshID := fmt.Sprintf("fresh-%d", instant.Unix())
101			fresh, err := b.Quote(QuoteRequest{
102				RequestID: freshID, ItemID: "seat", VersionID: "v-next", Quantity: 3,
103			})
104			if err != nil {
105				t.Fatalf("%v 新标识报价: %v", instant, err)
106			}
107			if !fresh.Confirmed || fresh.Reason != ReasonNone {
108				t.Fatalf("%v 版本已生效，新标识报价应确认: %+v", instant, fresh)
109			}
110			if fresh.UnitPrice != 250 || fresh.Total != 750 {
111				t.Fatalf("%v 新报价金额: 单价=%d 总价=%d, want 250/750", instant, fresh.UnitPrice, fresh.Total)
112			}
113			if !fresh.AcceptedAt.Equal(instant) {
114				t.Fatalf("%v 新报价受理时刻=%v", instant, fresh.AcceptedAt)
115			}
116	
117			// 新报价确认后，原请求的确认状态、拒绝原因、金额与首次受理时刻不变；
118			// 双方各自按标识查询，互不覆盖。
119			gotOld, err := b.Lookup("early")
120			if err != nil {
121				t.Fatalf("%v 新报价确认后查询原标识: %v", instant, err)
122			}
123			if gotOld != first {
124				t.Fatalf("%v 新报价确认改写了原请求的结果: %+v -> %+v", instant, first, gotOld)
125			}
126			gotFresh, err := b.Lookup(freshID)
127			if err != nil {
128				t.Fatalf("%v 查询新标识: %v", instant, err)
129			}
130			if gotFresh != fresh {
131				t.Fatalf("%v 新标识查询结果不一致: %+v vs %+v", instant, fresh, gotFresh)
132			}
133			if gotOld == gotFresh {
134				t.Fatalf("%v 两份结果应可稳定区分: %+v", instant, gotOld)
135			}
136		}
137	
138		// 两个时刻都走过后，原标识的结果依旧是 at(50) 的首次拒绝。
139		final, err := b.Lookup("early")
140		if err != nil {
141			t.Fatal(err)
142		}
143		if final != first {
144			t.Fatalf("原标识的最终结果被改写: %+v -> %+v", first, final)
145		}
146	}
147

